import{BASE_COATS,COATS,EVOLUTION,newGame,move,spawn,canMove}from'./core.mjs';
const $=id=>document.getElementById(id),KEY='catvolution.v1';const rareFallback={tortie:'orange',tuxedo:'black',cream:'white',silver:'gray',smoke:'black',peach:'orange',calico:'white'};let starter=null,board=[],score=0,undo=null,sound=true,discovered=new Set(BASE_COATS),highest={},audio;
function load(){try{const s=JSON.parse(localStorage.getItem(KEY)||'{}');(s.discovered||[]).forEach(x=>COATS[x]&&discovered.add(x));highest=s.highest||{};sound=s.sound!==false;starter=s.starter&&COATS[s.starter]?s.starter:null;const best=Number(s.best)||0;$('best').textContent=best}catch{}}
function save(){try{const old=JSON.parse(localStorage.getItem(KEY)||'{}');localStorage.setItem(KEY,JSON.stringify({...old,discovered:[...discovered],highest,sound,starter,best:Math.max(Number(old.best)||0,score)}))}catch{}}
function image(coat){return`cats/${BASE_COATS.includes(coat)?coat:rareFallback[coat]}.webp`}
function beep(){if(!sound)return;try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=520;g.gain.setValueAtTime(.04,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.09);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.1)}catch{}}
function renderOptions(){const available=[...BASE_COATS,...[...discovered].filter(x=>!BASE_COATS.includes(x))];$('cat-options').innerHTML=available.map(c=>`<button class="cat-card" data-coat="${c}" aria-pressed="${starter===c}"><img src="${image(c)}" alt="${COATS[c][0]}"><div><strong>${COATS[c][0]}</strong><span>${COATS[c][1]}</span></div></button>`).join('');document.querySelectorAll('[data-coat]').forEach(b=>b.onclick=()=>{starter=b.dataset.coat;save();renderOptions();$('start').disabled=false})}
function render(){const max=Math.max(2,...board.filter(Boolean).map(t=>t.value));$('board').innerHTML=board.map(t=>`<div class="cell">${t?`<div class="tile ${BASE_COATS.includes(t.coat)?'':'rare'} ${t.value>=1024?'king':''} ${t.value>=2048?'god':''}"><img src="${image(t.coat)}" alt=""><span class="coat-dot">${COATS[t.coat][0]}</span><b class="value">${t.value}</b></div>`:''}</div>`).join('');$('score').textContent=score;$('best').textContent=Math.max(Number($('best').textContent)||0,score);$('highest').textContent=`${EVOLUTION[max]||'Legendary Cat'} · ${max}`;$('undo').disabled=!undo;for(const t of board.filter(Boolean))highest[t.coat]=Math.max(highest[t.coat]||0,t.value);save();renderCollection()}
function renderCollection(){$('collection-count').textContent=`${discovered.size}/11`;$('collection-progress').textContent=`${discovered.size} / 11 coats discovered`;$('collection-grid').innerHTML=Object.entries(COATS).map(([id,[name,desc]])=>{const open=discovered.has(id);return`<article class="collection-card">${open?`<img src="${image(id)}" alt="${name}">`:'<div class="locked">?</div>'}<div><strong>${open?name:'Unknown coat'}</strong><small>${open?`${desc} · Best ${highest[id]||2}`:'Keep mixing cats to unlock.'}</small></div></article>`}).join('')}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').classList.remove('show'),2400)}
function begin(){if(!starter)return;board=newGame(starter);score=0;undo=null;$('select-screen').hidden=true;$('game-screen').hidden=false;$('status').textContent='Swipe or use arrow keys. Equal numbers merge—even with different coats.';render()}
function act(direction){const before=board.map(t=>t&&({...t})),previousScore=score;const result=move(board,direction);if(!result.changed)return;undo={board:before,score:previousScore};board=spawn(result.board,starter);score+=result.score;for(const coat of result.discoveries){if(!discovered.has(coat)){discovered.add(coat);toast(`NEW CAT DISCOVERED: ${COATS[coat][0]}!`);$('status').textContent=`${COATS[coat][1]}. Added to your collection.`}}if(result.score){beep();const max=Math.max(...board.filter(Boolean).map(t=>t.value));const messages={64:'Your cat has discovered food.',128:'Chonk level increasing.',256:'The vet is concerned.',512:'This is no longer a house cat.',1024:'ALL HAIL THE CAT KING.',2048:'YOUR CAT HAS ASCENDED.'};if(messages[max])$('status').textContent=messages[max]}render();if(!canMove(board))$('game-over').showModal()}
load();renderOptions();renderCollection();$('start').disabled=!starter;$('start').onclick=begin;$('random').onclick=()=>{const choices=[...discovered];starter=choices[Math.floor(Math.random()*choices.length)];renderOptions();$('start').disabled=false};$('home').onclick=()=>{$('game-screen').hidden=true;$('select-screen').hidden=false;renderOptions()};$('restart').onclick=begin;$('again').onclick=()=>{$('game-over').close();begin()};$('undo').onclick=()=>{if(!undo)return;board=undo.board;score=undo.score;undo=null;$('status').textContent='Time reversed. The discovery stays in your collection.';render()};$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',sound);save()};$('sound').textContent=sound?'Sound on':'Sound off';$('collection-open').onclick=()=>{$('collection').showModal();renderCollection()};$('collection-close').onclick=()=>$('collection').close();
const dirs={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down'};addEventListener('keydown',e=>{if(!$('game-screen').hidden&&dirs[e.key]){e.preventDefault();act(dirs[e.key])}});let sx=0,sy=0;$('board').addEventListener('pointerdown',e=>{sx=e.clientX;sy=e.clientY});$('board').addEventListener('pointerup',e=>{const dx=e.clientX-sx,dy=e.clientY-sy;if(Math.max(Math.abs(dx),Math.abs(dy))<25)return;act(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up')});
